namespace WebApi.Models;

/// <summary>Represents the lifecycle status of an order.</summary>
public enum OrderStatus
{
    Pending,
    Processing,
    Shipped,
    Delivered,
    Cancelled
}

namespace WebApi.Models;

/// <summary>Internal domain entity for an order.</summary>
public sealed class Order
{
    public int Id { get; set; }
    public int CustomerId { get; set; }
    public DateTimeOffset PlacedAt { get; set; }
    public decimal TotalAmount { get; set; }
    public OrderStatus Status { get; set; }
}

namespace WebApi.Models;

/// <summary>Represents an order returned by the API.</summary>
public sealed record OrderResponse(
    int Id,
    int CustomerId,
    DateTimeOffset PlacedAt,
    decimal TotalAmount,
    OrderStatus Status);

using System.ComponentModel.DataAnnotations;

namespace WebApi.Models;

/// <summary>Payload for creating a new order.</summary>
public sealed record CreateOrderRequest
{
    [Required]
    public required int CustomerId { get; init; }

    [Required]
    public required DateTimeOffset PlacedAt { get; init; }

    [Range(0.01, (double)decimal.MaxValue)]
    public required decimal TotalAmount { get; init; }

    [Required]
    public required OrderStatus Status { get; init; }
}

using WebApi.Models;

namespace WebApi.Services;

public interface IOrderService
{
    Task<IReadOnlyList<OrderResponse>> GetAllAsync(CancellationToken ct);
    Task<OrderResponse?> GetByIdAsync(int id, CancellationToken ct);
    Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken ct);
}

using WebApi.Models;

namespace WebApi.Services;

public sealed class OrderService : IOrderService
{
    private readonly List<Order> _orders = [];
    private int _nextId = 1;

    public Task<IReadOnlyList<OrderResponse>> GetAllAsync(CancellationToken ct)
    {
        IReadOnlyList<OrderResponse> result = _orders
            .Select(o => ToResponse(o))
            .ToList();
        return Task.FromResult(result);
    }

    public Task<OrderResponse?> GetByIdAsync(int id, CancellationToken ct)
    {
        var order = _orders.Find(o => o.Id == id);
        return Task.FromResult(order is null ? null : ToResponse(order));
    }

    public Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken ct)
    {
        var order = new Order
        {
            Id = _nextId++,
            CustomerId = request.CustomerId,
            PlacedAt = request.PlacedAt,
            TotalAmount = request.TotalAmount,
            Status = request.Status
        };

        _orders.Add(order);
        return Task.FromResult(ToResponse(order));
    }

    private static OrderResponse ToResponse(Order o) =>
        new(o.Id, o.CustomerId, o.PlacedAt, o.TotalAmount, o.Status);
}

